def solution(input_str):
    ns = str(input_str).strip().split('\n')
    first_line = ns[0].split()
    n, k = int(first_line[0]), int(first_line[1])
    a = list(map(int, ns[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    def solve(current_nums, operations, depth):
        # Base case: only one number left
        if len(current_nums) == 1:
            if current_nums[0] == 1:
                return operations[:]
            else:
                return None

        # Try to pick any two numbers and combine them
        for i in range(len(current_nums)):
            for j in range(i + 1, len(current_nums)):
                x, y = current_nums[i], current_nums[j]
                new_val = f(x + y)

                # Create new list without x and y, and add new_val
                new_nums = [current_nums[k] for k in range(len(current_nums)) if k != i and k != j]
                new_nums.append(new_val)

                # Recurse
                new_operations = operations + [(x, y)]
                result = solve(new_nums, new_operations, depth + 1)

                if result is not None:
                    return result

        return None

    # Start the search
    result = solve(a, [], 0)

    if result is None:
        return "NO"
    else:
        output_lines = ["YES"]
        for x, y in result:
            output_lines.append(f"{x} {y}")
        return "\n".join(output_lines)
