    lines = s.strip().split('\n')
    n = int(lines[0])
    edges = []
    for i in range(1, n):
        parts = lines[i].split()
        edges.append((int(parts[0]), int(parts[1])))
    return n, edges

def solution(input_str):
    n, edges = parse_input(input_str)
    return str(solve(n, edges))
