# Solution for the Formula One Ticket problem

def nCr(n, r):
    """Calculate binomial coefficient C(n, r)"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result

def count_valid_sequences(n, m, k):
    """
    Use dynamic programming to count the number of valid sequences
    where Charlie never runs out of change.
    """
    if k <= 0 and m > 0:
        return 0

    # If initial k covers all 20s, all sequences are valid
    if k >= m:
        return nCr(n + m, n)

    # DP with memoization
    dp = {}

    def count_dp(rem_n, rem_m, balance):
        if rem_n == 0 and rem_m == 0:
            return 1

        if balance < 0:
            return 0

        state = (rem_n, rem_m, balance)
        if state in dp:
            return dp[state]

        result = 0
        # Person with 10 euro arrives: balance increases by 1
        if rem_n > 0:
            result += count_dp(rem_n - 1, rem_m, balance + 1)

        # Person with 20 euro arrives: balance decreases by 1 (give 1 for change)
        if rem_m > 0 and balance > 0:
            result += count_dp(rem_n, rem_m - 1, balance - 1)

        dp[state] = result
        return result

    return count_dp(n, m, k)

def solution(input_str):
    """
    Calculate the probability that Charlie can always provide change.
    """
    parts = input_str.strip().split()
    n = int(parts[0])
    m = int(parts[1])
    k = int(parts[2])

    # Edge case: no people
    if n == 0 and m == 0:
        return '1\n'

    # Edge case: if k >= m, all 20 euro people can always be change-given
    # (since we need m euros worth of change originally, and have k >= m)
    if k >= m:
        return '1\n'

    # If k == 0 and there are any 20s, need to validate sequences
    if k == 0 and m > 0:
        valid = count_valid_sequences(n, m, k)
    else:
        valid = count_valid_sequences(n, m, k)

    total = nCr(n + m, n)
    probability = valid / total

    return f"{probability:.12f}\n"


if __name__ == "__main__":
    import sys
    print(solution(sys.stdin.read()))
