    ]

    # Track current count and best configuration
    grid = [['.' for _ in range(m)] for _ in range(n)]
    best_count = [0]
    best_grid = [row[:] for row in grid]

    def can_place(r, c, shape):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= m:
                return False
            if grid[nr][nc] != '.':
                return False
        return True

    def place(r, c, shape, char_idx):
        for dr, dc in shape:
            grid[r + dr][c + dc] = chr(ord('A') + char_idx)

    def remove(r, c, shape):
        for dr, dc in shape:
            grid[r + dr][c + dc] = '.'

    def dfs(start_idx, count):
        nonlocal best_count, best_grid

        if count > best_count[0]:
            best_count[0] = count
            best_grid = [row[:] for row in grid]

        # Find first empty cell at or after start_idx row
        for i in range(start_idx, n):
            for j in range(m):
                if grid[i][j] == '.':
                    break

            if j >= m:
                continue

            # Try all 4 orientations at this position
            for shape in t_shapes:
                if can_place(i, j, shape):
                    c_idx = count - 1
                    place(i, j, shape, c_idx)
                    dfs(i, count + 1)
                    remove(i, j, shape)

        # Continue even if we found placement, to explore more options
        dfs(start_idx + 1, count)

    # Start DFS from position (0, 0)
    dfs(0, 0)

    # Build result
    result_lines = [str(best_count[0])] + [''.join(row) for row in best_grid]
