The problem involves reconstructing the smallest possible integer `n` from a shuffled string that contains digits of `n` plus the digits representing `k` (where `k` is the number of digits in `n`). We're also given a substring of `n` that must appear in the reconstructed number.

```python
from collections import Counter

def solution(input_str):
    lines = input_str.split('\n', 1)
    shuffled = lines[0].strip()
    substring = lines[1].strip()

    total_len = len(shuffled)

    for d in range(1, total_len + 1):
        k_len = len(str(d))
        if d + k_len != total_len:
            continue

        k_str = str(d)
        pool = Counter(shuffled)
        k_count = Counter(k_str)

        n_pool = {}
        for ch in pool:
            n_pool[ch] = pool[ch] - k_count.get(ch, 0)

        n_pool = {ch: cnt for ch, cnt in n_pool.items() if cnt > 0}

        total_remaining = sum(n_pool.values())
        if total_remaining != d:
            continue

        sub_counter = Counter(substring)
        valid = True
        for ch, count in sub_counter.items():
            if n_pool.get(ch, 0) < count:
                valid = False
                break

        if not valid:
            continue

        chars = sorted(n_pool.elements())

        if d == 1:
            return chars[0]

        # Find smallest non-zero character for leading position
        non_zero_chars = [c for c in chars if c != '0']
        if non_zero_chars:
            leading = non_zero_chars[0]
            # Put leading char first, then zeros, then rest
            result = [leading] + [c for c in chars if c != leading]
        else:
            result = chars

        n = ''.join(result)

        if substring in n:
            return n

    return ""
